*{box-sizing:border-box;margin:0;padding:0}
:root{
  --mono:ui-monospace,"SF Mono",SFMono-Regular,Menlo,Consolas,"Liberation Mono",monospace;
  --serif:"Didot","Bodoni MT","Playfair Display","Georgia Pro",Georgia,"Times New Roman",serif;
  --ink:#edf2fb;
  --muted:rgba(213,227,248,.55);
  --cloud:#c7d3e4;
  --accent:#ffb54d; --accent-2:#ff7e5f;
  --bg-a:#1b2145; --bg-b:#43284e; --bg-c:#07091a;
  --glow:rgba(255,178,80,.45);
}
body[data-theme="night"] {--accent:#ffe9a8;--accent-2:#8ea2ff;--bg-a:#0a0f22;--bg-b:#1c2242;--bg-c:#04060f;--glow:rgba(255,233,170,.35)}
body[data-theme="partly"]{--accent:#ffcf70;--accent-2:#7fb2ff;--bg-a:#1a2340;--bg-b:#31406b;--bg-c:#070b18;--glow:rgba(255,207,112,.4)}
body[data-theme="cloudy"]{--accent:#a9c1d9;--accent-2:#6c86a8;--bg-a:#171e2e;--bg-b:#2c3850;--bg-c:#080b13;--glow:rgba(169,193,217,.35)}
body[data-theme="fog"]   {--accent:#c2cfd6;--accent-2:#8fa6b3;--bg-a:#1a212b;--bg-b:#333f4c;--bg-c:#0a0e14;--glow:rgba(194,207,214,.3)}
body[data-theme="rain"]  {--accent:#6fb7ff;--accent-2:#4f7fe0;--bg-a:#0f1c33;--bg-b:#20365c;--bg-c:#060a14;--glow:rgba(111,183,255,.4)}
body[data-theme="snow"]  {--accent:#d6ebff;--accent-2:#89b8e8;--bg-a:#13203a;--bg-b:#2b4468;--bg-c:#070c16;--glow:rgba(214,235,255,.45)}
body[data-theme="storm"] {--accent:#c09aff;--accent-2:#ffd166;--bg-a:#150f2c;--bg-b:#31204f;--bg-c:#070512;--glow:rgba(192,154,255,.45)}
body[data-theme="error"] {--accent:#ff7d7d;--accent-2:#ff9f6e;--bg-a:#241016;--bg-b:#3c1b24;--bg-c:#0c0508;--glow:rgba(255,125,125,.4)}

html,body{height:100%}
body{
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Inter,Roboto,Helvetica,Arial,sans-serif;
  color:var(--ink);
  background:linear-gradient(165deg,var(--bg-b) 0%,var(--bg-a) 48%,var(--bg-c) 100%);
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  min-height:100%;padding:26px 18px;overflow:auto;position:relative;
}
::selection{background:var(--accent);color:#0a0d18}

.blob{position:fixed;border-radius:50%;filter:blur(90px);pointer-events:none;z-index:0}
.b1{width:540px;height:540px;left:-140px;top:-160px;background:var(--accent);opacity:.16;animation:drift1 26s ease-in-out infinite alternate}
.b2{width:640px;height:640px;right:-180px;bottom:-220px;background:var(--accent-2);opacity:.14;animation:drift2 32s ease-in-out infinite alternate}
@keyframes drift1{to{transform:translate(70px,50px) scale(1.15)}}
@keyframes drift2{to{transform:translate(-60px,-60px) scale(1.08)}}
.gridlay{position:fixed;inset:0;z-index:0;pointer-events:none;
  background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);
  background-size:56px 56px;
  -webkit-mask-image:radial-gradient(ellipse at 50% 42%,rgba(0,0,0,.85),transparent 74%);
  mask-image:radial-gradient(ellipse at 50% 42%,rgba(0,0,0,.85),transparent 74%);
}

.card{
  position:relative;z-index:2;width:min(1060px,94vw);border-radius:26px;overflow:hidden;
  background:linear-gradient(165deg,rgba(255,255,255,.10),rgba(255,255,255,.035) 55%,rgba(255,255,255,.06));
  border:1px solid rgba(255,255,255,.14);
  box-shadow:0 44px 110px -34px rgba(0,0,0,.75),inset 0 1px 0 rgba(255,255,255,.14);
  backdrop-filter:blur(20px) saturate(1.2);-webkit-backdrop-filter:blur(20px) saturate(1.2);
  animation:reveal .7s cubic-bezier(.2,.7,.2,1) both;
}
@keyframes reveal{from{opacity:0;transform:translateY(22px) scale(.985)}to{opacity:1;transform:none}}

.ribbon{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:14px 30px;
  border-bottom:1px solid rgba(255,255,255,.10);font-family:var(--mono);
  font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;color:var(--muted);white-space:nowrap}
.rleft{display:flex;align-items:center;gap:16px;min-width:0}
.rtitle{overflow:hidden;text-overflow:ellipsis}
.badge{display:inline-flex;align-items:center;gap:7px;padding:5px 12px;border-radius:999px;flex:0 0 auto;
  border:1px solid rgba(255,255,255,.25);border-color:color-mix(in srgb,var(--accent) 55%,transparent);
  color:var(--accent);background:rgba(255,255,255,.04);background:color-mix(in srgb,var(--accent) 12%,transparent);
  font-size:10px;letter-spacing:.2em}
.badge .dot{width:6px;height:6px;border-radius:50%;background:var(--accent);animation:blink 2.2s ease-in-out infinite}
@keyframes blink{0%,100%{opacity:1}50%{opacity:.25}}

.main{display:grid;grid-template-columns:1.15fr .85fr;padding:30px 36px 8px}
.hero{padding-right:36px;min-width:0}
.loc{font-family:var(--serif);font-size:clamp(30px,3.4vw,44px);font-weight:600;line-height:1.05;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dateline{margin-top:9px;font-family:var(--mono);font-size:11px;letter-spacing:.22em;color:var(--muted)}
.reading{display:flex;align-items:center;gap:26px;margin-top:20px}
.glyph{flex:0 0 auto}
.glyph svg{width:148px;height:148px;overflow:visible;filter:drop-shadow(0 0 26px var(--glow))}
.temp{font-family:var(--serif);font-size:116px;line-height:.85;font-weight:500;letter-spacing:-.02em;display:flex;align-items:flex-start}
.temp .unit{font-size:30px;margin:12px 0 0 7px;color:var(--muted)}
.cond{margin-top:15px;font-family:var(--serif);font-style:italic;font-size:26px;color:var(--accent)}
.condsub{margin-top:9px;font-family:var(--mono);font-size:10.5px;letter-spacing:.2em;color:var(--muted);text-transform:uppercase}

.stats{border-left:1px solid rgba(255,255,255,.10);padding-left:36px;display:grid;
  grid-template-columns:1fr 1fr;gap:22px 24px;align-content:center}
.stat .k{font-family:var(--mono);font-size:9.5px;letter-spacing:.24em;color:var(--muted);margin-bottom:7px;text-transform:uppercase}
.stat .v{font-size:21px;font-weight:600;font-variant-numeric:tabular-nums;display:flex;align-items:baseline;gap:6px;flex-wrap:wrap}
.stat .u{font-size:12px;color:var(--muted);font-weight:500}
.sep{color:var(--muted);font-weight:400}
.warrow{width:15px;height:15px;color:var(--accent);align-self:center;flex:0 0 auto}

.chartsec{padding:16px 36px 26px}
.chead{display:flex;justify-content:space-between;font-family:var(--mono);font-size:10px;
  letter-spacing:.24em;color:var(--muted);text-transform:uppercase;margin-bottom:8px}
.chartsec svg{width:100%;height:auto;display:block}
.gl{stroke:rgba(255,255,255,.09)}
.glab,.mlab,.nlab,.ttt,.ttv{font-family:var(--mono)}
.glab{fill:var(--muted);font-size:10.5px}
.mlab{fill:var(--ink);font-size:11.5px;font-weight:600}
.xdot{fill:var(--accent);stroke:rgba(6,10,20,.6);stroke-width:2}
.pbar{fill:var(--accent-2);opacity:.5}
.nowl{stroke:var(--accent-2);stroke-width:1.5;stroke-dasharray:3 5;opacity:.85}
.nlab{fill:var(--accent-2);font-size:9px;letter-spacing:.2em}
.tline{fill:none;stroke:var(--accent);stroke-width:3;stroke-linecap:round;stroke-linejoin:round;
  stroke-dasharray:1;stroke-dashoffset:1;animation:draw 1.5s .2s cubic-bezier(.4,0,.2,1) forwards;
  filter:drop-shadow(0 3px 8px var(--glow))}
@keyframes draw{to{stroke-dashoffset:0}}
.tarea{opacity:0;animation:fadein .9s 1s forwards}
@keyframes fadein{to{opacity:1}}
.ttline{stroke:rgba(255,255,255,.3);stroke-dasharray:2 4}
.ttdot{fill:var(--accent);stroke:rgba(4,8,16,.7);stroke-width:2}
.ttbox{fill:rgba(7,11,22,.94);stroke:rgba(255,255,255,.16)}
.ttt{fill:rgba(220,232,250,.6);font-size:10px;letter-spacing:.14em}
.ttv{fill:#fff;font-size:13px;font-weight:600}
.nochart{padding:44px;text-align:center;font-family:var(--mono);letter-spacing:.2em;font-size:11px;
  color:var(--muted);border:1px dashed rgba(255,255,255,.15);border-radius:14px}

.spin{animation:spin 42s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.drop{animation:fall 1.15s ease-in infinite}
.d1{animation-delay:.38s}.d2{animation-delay:.76s}
@keyframes fall{0%{transform:translateY(-8px);opacity:0}25%{opacity:1}80%{opacity:1}100%{transform:translateY(16px);opacity:0}}
.flake{animation:flake 2.4s linear infinite}
.k1{animation-delay:.8s}.k2{animation-delay:1.6s}
@keyframes flake{0%{transform:translate(0,-10px);opacity:0}20%{opacity:1}100%{transform:translate(-6px,18px);opacity:0}}
.fg{animation:fog 5s ease-in-out infinite alternate}
.f2{animation-delay:1.2s}.f3{animation-delay:2.2s}
@keyframes fog{from{transform:translateX(-5px);opacity:.45}to{transform:translateX(6px);opacity:1}}
.bolt{animation:flash 2.8s infinite}
@keyframes flash{0%,55%,60%,100%{opacity:1}56%,58.5%{opacity:.12}57%{opacity:1}}
.tw{animation:tw 3s ease-in-out infinite}
.t2{animation-delay:1s}.t3{animation-delay:2s}
@keyframes tw{0%,100%{opacity:.25}50%{opacity:1}}

.loading{padding:150px 40px;display:flex;flex-direction:column;align-items:center;gap:26px}
.pulse{width:12px;height:12px;border-radius:50%;background:var(--accent);animation:ping 1.4s ease-out infinite}
@keyframes ping{0%{box-shadow:0 0 0 0 var(--glow)}80%{box-shadow:0 0 0 26px rgba(0,0,0,0)}100%{box-shadow:0 0 0 0 rgba(0,0,0,0)}}
.lmsg{font-family:var(--mono);letter-spacing:.24em;font-size:11px;color:var(--muted)}

.errwrap{padding:52px 60px 58px;display:flex;flex-direction:column;align-items:center;text-align:center;gap:15px}
.errico{width:92px;height:92px;filter:drop-shadow(0 0 22px var(--glow))}
.errwrap h1{font-family:var(--serif);font-size:34px;font-weight:600}
.emsg{max-width:600px;color:var(--muted);font-size:15px;line-height:1.65}
.ereq{font-family:var(--mono);font-size:10px;letter-spacing:.18em;color:var(--muted);text-transform:uppercase}
.ehint{font-family:var(--mono);font-size:11px;letter-spacing:.06em;color:var(--muted);
  background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);padding:9px 16px;border-radius:8px}
.retry{margin-top:8px;font-family:var(--mono);font-size:11px;letter-spacing:.22em;color:var(--accent);
  background:transparent;border:1px solid var(--accent);border-radius:999px;padding:11px 26px;cursor:pointer;transition:.25s}
.retry:hover{background:var(--accent);color:#10131f}

.pfoot{z-index:2;margin-top:18px;font-family:var(--mono);font-size:9.5px;letter-spacing:.26em;
  color:rgba(255,255,255,.32);text-transform:uppercase;text-align:center}

@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important}
  .tline{stroke-dasharray:none;stroke-dashoffset:0}
  .tarea{opacity:1}
}

