  pts.forEach(function(p){p.x=X(p.i);p.y=Y(p.t);});
  var g="";[hi,(hi+lo)/2,lo].forEach(function(v){var y=Y(v);
    g+='<line class="gl" x1="'+pl+'" x2="'+(W-pr)+'" y1="'+y.toFixed(1)+'" y2="'+y.toFixed(1)+'"/><text class="glab" x="'+(pl-10)+'" y="'+(y+3.5).toFixed(1)+'" text-anchor="end">'+Math.round(v)+'°</text>';});
  var xl="";for(i=0;i<N;i+=3)xl+='<text class="glab" x="'+X(i).toFixed(1)+'" y="'+(HT-12)+'" text-anchor="middle">'+String(times[i]||"").slice(11,16)+'</text>';
  var bars="",pmax=0.4;pts.forEach(function(p){if(p.p>pmax)pmax=p.p;});
  pts.forEach(function(p){if(p.p>0.02){var h=Math.max(2,p.p/pmax*26);
    bars+='<rect class="pbar" x="'+(p.x-3).toFixed(1)+'" y="'+(base-h).toFixed(1)+'" width="6" height="'+h.toFixed(1)+'" rx="2"/>';}});
  var xy=pts.map(function(p){return[p.x,p.y];});
  var line=smooth(xy);
  var area=line+" L"+xy[xy.length-1][0].toFixed(1)+" "+base+" L"+xy[0][0].toFixed(1)+" "+base+" Z";
  var pMax=pts[0],pMin=pts[0];pts.forEach(function(p){if(p.t>pMax.t)pMax=p;if(p.t<pMin.t)pMin=p;});
  function mark(p,above){return '<circle class="xdot" cx="'+p.x.toFixed(1)+'" cy="'+p.y.toFixed(1)+'" r="4"/><text class="mlab" x="'+p.x.toFixed(1)+'" y="'+(above?p.y-11:p.y+19).toFixed(1)+'" text-anchor="middle">'+d1(p.t)+'°</text>';}
  var now="";
  if(nowFrac!=null&&N>1){var nx=pl+Math.min(nowFrac,N-1)/(N-1)*(W-pl-pr);
    now='<line class="nowl" x1="'+nx.toFixed(1)+'" x2="'+nx.toFixed(1)+'" y1="'+(pt-6)+'" y2="'+base+'"/><text class="nlab" x="'+nx.toFixed(1)+'" y="'+(pt-12)+'" text-anchor="middle">NOW</text>';}
  var html='<svg id="hchart" viewBox="0 0 '+W+' '+HT+'" role="img" aria-label="Hourly temperature chart">'
    +'<defs><linearGradient id="ag" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="var(--accent)" stop-opacity=".32"/><stop offset="1" stop-color="var(--accent)" stop-opacity="0"/></linearGradient></defs>'
    +g+bars
    +'<path class="tarea" d="'+area+'" fill="url(#ag)"/>'
    +'<path class="tline" pathLength="1" d="'+line+'"/>'
    +now+mark(pMax,true)+mark(pMin,false)+xl
    +'<g id="tt" style="display:none;pointer-events:none">'
    +'<line id="ttl" class="ttline" y1="'+pt+'" y2="'+base+'"/>'
    +'<circle id="ttd" class="ttdot" r="4.5"/>'
    +'<g id="ttb"><rect class="ttbox" width="118" height="44" rx="9"/><text class="ttt" id="tt1" x="59" y="18" text-anchor="middle"></text><text class="ttv" id="tt2" x="59" y="35" text-anchor="middle"></text></g>'
    +'</g>'
    +'<rect id="ov" x="'+(pl-8)+'" y="0" width="'+(W-pl-pr+16)+'" height="'+HT+'" fill="transparent" style="cursor:crosshair"/>'
    +'</svg>';
  return{html:html,pts:pts,W:W,pl:pl,pr:pr,unit:unit};
}
function wireChart(ch){
  if(!ch.pts.length)return;
  var svg=document.getElementById("hchart"),ov=document.getElementById("ov");
  var tt=document.getElementById("tt"),ttl=document.getElementById("ttl"),ttd=document.getElementById("ttd"),
      ttb=document.getElementById("ttb"),t1=document.getElementById("tt1"),t2=document.getElementById("tt2");
  if(!svg||!ov)return;
  ov.addEventListener("pointermove",function(e){
    var r=svg.getBoundingClientRect();
    var x=(e.clientX-r.left)*ch.W/r.width,best=ch.pts[0],bd=Infinity;
    ch.pts.forEach(function(p){var d=Math.abs(p.x-x);if(d<bd){bd=d;best=p;}});
    ttl.setAttribute("x1",best.x);ttl.setAttribute("x2",best.x);
    ttd.setAttribute("cx",best.x);ttd.setAttribute("cy",best.y);
    var bx=Math.max(ch.pl,Math.min(best.x-59,ch.W-ch.pr-118));
    var by=(best.y-58<6)?best.y+14:best.y-58;
    ttb.setAttribute("transform","translate("+bx.toFixed(1)+" "+by.toFixed(1)+")");
    t1.textContent=best.hh;
    t2.textContent=d1(best.t)+ch.unit+(best.p>0.05?" · "+d1(best.p)+" mm":"");
    tt.style.display="";
  });
  ov.addEventListener("pointerleave",function(){tt.style.display="none";});
}

/* ---------- render ---------- */
function coordStr(){return Math.abs(lat).toFixed(2)+"°"+(lat>=0?"N":"S")+" "+Math.abs(lon).toFixed(2)+"°"+(lon>=0?"E":"W");}
function modeLabel(){return dateStr<TODAY?"ARCHIVE":(dateStr===TODAY?"LIVE":"FORECAST");}

function render(data){
  var H=data.hourly||{},D=data.daily||{},cw=data.current_weather||null;
  var temps=H.temperature_2m||[];
  var unit=(data.hourly_units&&data.hourly_units.temperature_2m)||"°C";
  var wUnit=(data.hourly_units&&data.hourly_units.windspeed_10m)||"km/h";
  var live=(dateStr===TODAY)&&cw&&typeof cw.temperature==="number";
  var idx=pickIdx(temps);
  var repT,repLabel,wcode,wind,wdir,nowFrac=null;
  if(live){
    repT=cw.temperature;repLabel="now";wcode=cw.weathercode;wind=cw.windspeed;wdir=cw.winddirection;
    if(typeof cw.time==="string"&&cw.time.slice(0,10)===dateStr){
      nowFrac=(+cw.time.slice(11,13))+((+cw.time.slice(14,16))||0)/60;
    }
  }else{
    repT=idx>=0?temps[idx]:null;
    repLabel=idx>=0?("at "+hhmm(H.time[idx])):"";
    wcode=(D.weathercode||[])[0];
    if(wcode==null)wcode=(H.weathercode||[])[idx];
    wind=(H.windspeed_10m||[])[idx];
    if(wind==null)wind=(D.windspeed_10m_max||[])[0];
    wdir=(H.winddirection_10m||[])[idx];
  }
  var valid=temps.filter(function(v){return v!=null;});
  var tmax=(D.temperature_2m_max||[])[0];if(tmax==null&&valid.length)tmax=Math.max.apply(null,valid);
  var tmin=(D.temperature_2m_min||[])[0];if(tmin==null&&valid.length)tmin=Math.min.apply(null,valid);
  var hIdx=(live&&nowFrac!=null)?Math.min(temps.length-1,Math.floor(nowFrac)):idx;
  var hum=(H.relativehumidity_2m||[])[hIdx];
  var feels=(H.apparent_temperature||[])[hIdx];
  var psum=(D.precipitation_sum||[])[0];
  if(psum==null&&H.precipitation)psum=H.precipitation.reduce(function(a,v){return a+(v||0);},0);
  var sr=hhmm((D.sunrise||[])[0]),ss=hhmm((D.sunset||[])[0]);
  var wc=(wcode!=null&&WMO[wcode])?WMO[wcode]:[wcode!=null?("Weather code "+wcode):"Conditions unreported","cloudy"];
  var desc=wc[0],cat=wc[1];
  if(cat==="clear"&&live&&cw.is_day===0)cat="night";
  document.body.dataset.theme=cat;
  document.title=name+" · "+dateStr+" — Weather";
  var ch=buildChart(H,unit,nowFrac);
  var feelsStr=(feels!=null)?("FEELS "+d1(feels)+"° · "):"";
  function stat(k,v){return '<div class="stat"><div class="k">'+k+'</div><div class="v">'+v+'</div></div>';}
  var windV=(wind!=null)?(d1(wind)+'<span class="u">'+esc(wUnit)+'</span>'
    +(wdir!=null?'<svg class="warrow" viewBox="0 0 24 24" style="transform:rotate('+(((wdir+180)%360)).toFixed(0)+'deg)"><path d="M12 2.5l5.2 9.4h-3.6v9.6h-3.2v-9.6H6.8z" fill="currentColor"/></svg><span class="u">'+compass(wdir)+'</span>':"")):"—";
  card.innerHTML=
    '<div class="ribbon">'
      +'<div class="rleft"><span class="badge"><span class="dot"></span>'+modeLabel()+'</span><span class="rtitle">Atmospheric field report</span></div>'
      +'<div class="rright">'+coordStr()+' · '+esc(data.timezone||"UTC")+'</div>'
    +'</div>'
    +'<div class="main">'
      +'<div class="hero">'
        +'<h1 class="loc" title="'+esc(name)+'">'+esc(name)+'</h1>'
        +'<div class="dateline">'+esc(fmtDate(dateStr).toUpperCase())+'</div>'
        +'<div class="reading">'
          +'<div class="glyph">'+iconSVG(cat)+'</div>'
          +'<div class="tblock">'
            +'<div class="temp">'+fmtBig(repT)+'<span class="unit">'+esc(unit)+'</span></div>'
            +'<div class="cond">'+esc(desc)+'</div>'
            +'<div class="condsub">'+feelsStr+'READING '+esc(repLabel.toUpperCase())+'</div>'
          +'</div>'
        +'</div>'
      +'</div>'
      +'<div class="stats">'
        +stat("High / Low",d1(tmax)+'°<span class="sep">/</span>'+d1(tmin)+'°')
        +stat("Wind",windV)
        +stat("Humidity",hum!=null?(Math.round(hum)+'<span class="u">%</span>'):"—")
        +stat("Precipitation",psum!=null?(d1(psum)+'<span class="u">mm</span>'):"—")
        +stat("Sunrise",sr)
        +stat("Sunset",ss)
      +'</div>'
    +'</div>'
    +'<div class="chartsec">'
      +'<div class="chead"><span>Hourly temperature · 24h</span><span>'+d1(tmin)+'° … '+d1(tmax)+'°</span></div>'
      +ch.html
    +'</div>';
  wireChart(ch);
}

function renderError(title,msg){
  document.body.dataset.theme="error";
  document.title="Weather — signal lost";
  var req=esc(name)+" · LAT "+esc(latRaw!=null?latRaw:String(lat))+" · LON "+esc(lonRaw!=null?lonRaw:String(lon))+" · "+esc(dateRaw!=null?dateRaw:dateStr);
  card.innerHTML=
    '<div class="ribbon">'
      +'<div class="rleft"><span class="badge"><span class="dot"></span>SIGNAL LOST</span><span class="rtitle">Atmospheric field report</span></div>'
      +'<div class="rright">/api/om</div>'
    +'</div>'
    +'<div class="errwrap">'
      +'<svg class="errico" viewBox="0 0 120 120"><path d="M60 16 L112 104 H8 Z" fill="none" stroke="var(--accent)" stroke-width="5" stroke-linejoin="round"/><line x1="60" y1="48" x2="60" y2="76" stroke="var(--accent)" stroke-width="6" stroke-linecap="round"/><circle cx="60" cy="90" r="4" fill="var(--accent)"/></svg>'
      +'<h1>'+esc(title)+'</h1>'
      +'<p class="emsg">'+esc(msg)+'</p>'
      +'<div class="ereq">Requested · '+req+'</div>'
      +'<div class="ehint">?lat=52.52&amp;lon=13.405&amp;name=Berlin&amp;date='+TODAY+'</div>'
      +'<button class="retry" onclick="location.reload()">Retry transmission</button>'
    +'</div>';
}

/* ---------- boot ---------- */
function init(){
  var v=latP.err||lonP.err||dateError();
  if(v)return renderError("Bad coordinates on the wire",v);
  document.title=name+" · "+dateStr+" — Weather";
  var chain;
  if(dateStr<TODAY){
    chain=getJSON(apiURL("archive")).then(function(d){
      if(!hasData(d))throw new Error("The archive returned no observations for this date and location.");
      return d;
    }).catch(function(err){
      /* recent past may not be in the archive yet — fall back to the forecast feed */
      return getJSON(apiURL("forecast")).then(function(d){
        if(!hasData(d))throw err;return d;
      },function(){throw err;});
    });
  }else{
    chain=getJSON(apiURL("forecast"));
  }
  chain.then(function(data){
    if(!hasData(data))throw new Error("The station returned an empty dataset for this location and date.");
    render(data);
  }).catch(function(err){
    renderError("Signal lost",(err&&err.message)?err.message:"Unknown failure while contacting the weather feed.");
  });
}
init();
})();
